import{_ as l,o as i,c as t,ag as o}from"./chunks/framework.D1K3FKSn.js";const e="/assets/page3-1-1.D40pE96G.png",n="/assets/page3-1-1.DDBylfo9.gif",r="/assets/page3-1-2.y1UiRs2g.gif",u=JSON.parse('{"title":"BFC 的形成和作用","description":"","frontmatter":{},"headers":[],"relativePath":"tiku/html-css/page3-1.md","filePath":"tiku/html-css/page3-1.md","lastUpdated":1730451540000}'),c={name:"tiku/html-css/page3-1.md"};function s(d,a,h,b,p,m){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="bfc-的形成和作用" tabindex="-1">BFC 的形成和作用 <a class="header-anchor" href="#bfc-的形成和作用" aria-label="Permalink to &quot;BFC 的形成和作用&quot;">​</a></h1><h2 id="相关问题" tabindex="-1">相关问题 <a class="header-anchor" href="#相关问题" aria-label="Permalink to &quot;相关问题&quot;">​</a></h2><ul><li>BFC 有什么用，如何触发</li><li>谈谈你对 BFC 的理解</li></ul><h2 id="回答关键点" tabindex="-1">回答关键点 <a class="header-anchor" href="#回答关键点" aria-label="Permalink to &quot;回答关键点&quot;">​</a></h2><p><code>盒模型</code> <code>视觉格式化模型</code> <code>包含块</code> <code>正常流</code></p><h3 id="bfc-是什么" tabindex="-1">BFC 是什么 <a class="header-anchor" href="#bfc-是什么" aria-label="Permalink to &quot;BFC 是什么&quot;">​</a></h3><p>BFC 全称为 block formatting context，中文为“块级格式化上下文”。它是一个只有块级盒子参与的独立块级渲染区域，它规定了内部的块级盒子如何布局，且与区域外部无关。</p><h3 id="bfc-有什么用" tabindex="-1">BFC 有什么用 <a class="header-anchor" href="#bfc-有什么用" aria-label="Permalink to &quot;BFC 有什么用&quot;">​</a></h3><ul><li>修复浮动元素造成的高度塌陷问题。</li><li>避免非期望的外边距折叠。</li><li>实现灵活健壮的自适应布局。</li></ul><h3 id="触发-bfc-的常见条件" tabindex="-1">触发 BFC 的常见条件 <a class="header-anchor" href="#触发-bfc-的常见条件" aria-label="Permalink to &quot;触发 BFC 的常见条件&quot;">​</a></h3><ul><li><code>&lt;html&gt;</code> 根元素。</li><li>float 的值不为 none。</li><li>position 的值不为 relative 或 static。</li><li>overflow 的值不为 visible 或 clip（除了根元素）。</li><li>display 的值为 table-cell，table-caption，或 inline-block 中的任意一个。</li><li>display 的值为 flow-root，或 display 值为 flow-root list-item。</li><li>flex items，即 display 的值为 flex 或 inline-flex 的元素的直接子元素（该子元素 display 不为 flex，grid，或 table）。</li><li>grid items，即 display 的值为 grid 或 inline-grid 的元素的直接子元素（该子元素 display 不为 flex，grid，或 table）。</li><li>contain 的值为 layout，content，paint，或 strict 中的任意一个。</li><li>column-span 设置为 all 的元素。</li></ul><blockquote><p>提示：<code>display: flow-root</code>，<code>contain: layout</code> 等是无副作用的，可在不影响已有布局的情况下触发 BFC。</p></blockquote><h2 id="知识点深入" tabindex="-1">知识点深入 <a class="header-anchor" href="#知识点深入" aria-label="Permalink to &quot;知识点深入&quot;">​</a></h2><h3 id="_1-前置知识点" tabindex="-1">1. 前置知识点 <a class="header-anchor" href="#_1-前置知识点" aria-label="Permalink to &quot;1. 前置知识点&quot;">​</a></h3><h4 id="盒模型-box-model" tabindex="-1">盒模型（box model） <a class="header-anchor" href="#盒模型-box-model" aria-label="Permalink to &quot;盒模型（box model）&quot;">​</a></h4><p><strong>盒模型</strong>描述了一个由元素生成的矩形盒子，视觉格式化模型决定这些盒子的大小、位置以及属性（例如颜色、背景、边框尺寸等等）。</p><p>盒子的具体构成如下图所示： <img src="'+e+'" alt="" loading="lazy"></p><h4 id="术语解析" tabindex="-1">术语解析 <a class="header-anchor" href="#术语解析" aria-label="Permalink to &quot;术语解析&quot;">​</a></h4><p>由于视觉格式化模型描述中，有许多相近的术语，在此先行列出解释。</p><ul><li>box（盒子）：一个抽象概念，在画布上占据一块空间，通常由元素（element）生成。一个元素可能生成多个盒子（如伪元素、list-item 元素）。</li><li>principal box（主要盒子）：元素生成的多个盒子中，用来包含它的后代盒子和它生成的内容的盒子，也是参与任何定位方案的盒子。</li><li>block-level box（块级盒子）：参与 BFC 布局的盒子，通常由块级元素生成。</li><li>block container box（块容器）：在 CSS2.2 中，除了 table box 或替换元素的主要盒子，一个块级盒子也是块容器，但不是所有的块容器都是块级盒子（如非替换内联块盒子）。块容器主要侧重于其子元素的定位、布局。</li><li>block box（块盒子）：如果一个块级盒子同时也是块容器，则可以称作块盒子。</li><li>block（块）：当没有歧义时，作为 block box, block-level box 或 block container box 的简写。</li></ul><blockquote><p>（注：盒子有“块盒子”和“块级盒子”，元素只有“块级元素”，而没有“块元素”）</p></blockquote><h3 id="_2-视觉格式化模型-visual-formatting-model" tabindex="-1">2. 视觉格式化模型（visual formatting model） <a class="header-anchor" href="#_2-视觉格式化模型-visual-formatting-model" aria-label="Permalink to &quot;2. 视觉格式化模型（visual formatting model）&quot;">​</a></h3><p>视觉格式化模型描述了用户代理（如浏览器）在可视化媒体（如显示器）上处理文档树（document tree）的过程。下面各小节是视觉格式化模型中与 BFC 强相关的描述：</p><h4 id="_2-1-包含块-containing-block" tabindex="-1">2.1 包含块（containing block） <a class="header-anchor" href="#_2-1-包含块-containing-block" aria-label="Permalink to &quot;2.1 包含块（containing block）&quot;">​</a></h4><p>大部分情况下，包含块是一个由元素最近的祖先块容器的内容区域（content area）确定的矩形区域，包含块本身不是盒子，是一个矩形区域。元素的大小，位置，及偏移等布局信息根据包含块的尺寸进行计算。</p><h4 id="_2-2-正常流-normal-flow" tabindex="-1">2.2 正常流（normal flow） <a class="header-anchor" href="#_2-2-正常流-normal-flow" aria-label="Permalink to &quot;2.2 正常流（normal flow）&quot;">​</a></h4><p>正常流是浏览器的默认布局方式。在正常流中的盒子，属于 BFC，IFC，或其他格式化上下文之一。</p><h4 id="_2-3-格式化上下文-formatting-context" tabindex="-1">2.3 格式化上下文（formatting context） <a class="header-anchor" href="#_2-3-格式化上下文-formatting-context" aria-label="Permalink to &quot;2.3 格式化上下文（formatting context）&quot;">​</a></h4><p><strong>格式化上下文</strong>是一系列相关盒子进行布局的环境。不同的格式化上下文有不同的布局规则。目前常见的格式化上下文有以下这些：</p><ul><li>块级格式化上下文（BFC，block formatting context）。</li><li>内联格式化上下文（IFC，inline formatting context）。</li><li>弹性格式化上下文（FFC，flex formatting context），在 CSS3 中定义。</li><li>栅格格式化上下文（GFC，grid formatting context），在 CSS3 中定义。</li></ul><h4 id="_2-4-独立格式化上下文-independent-formatting-context" tabindex="-1">2.4 独立格式化上下文（independent formatting context） <a class="header-anchor" href="#_2-4-独立格式化上下文-independent-formatting-context" aria-label="Permalink to &quot;2.4 独立格式化上下文（independent formatting context）&quot;">​</a></h4><p>一个盒子要么建立一个新的独立格式化上下文，要么延续其包含块的格式化上下文。除了特殊说明，建立新的格式化上下文就是在建立一个独立格式化上下文。</p><p>当一个盒子建立一个独立格式化上下文时，它创建了一个新的独立布局环境。除了通过改变盒子本身的大小，盒子内部的后代不会影响格式化上下文外部的规则和内容，反之亦然。</p><h4 id="_2-5-块级格式化上下文规范及解析" tabindex="-1">2.5 块级格式化上下文规范及解析 <a class="header-anchor" href="#_2-5-块级格式化上下文规范及解析" aria-label="Permalink to &quot;2.5 块级格式化上下文规范及解析&quot;">​</a></h4><p>根据 W3C CSS2.1 视觉格式化模型一章的定义，BFC 相关规范描述如下：</p><ol><li>浮动元素，绝对定位元素，不是块级盒子的块级容器（如 inline-block，table-cells，table-captions）以及 overflow 值不为 visible 的块级盒子，都会为他们的内容创建 BFC（注：触发 BFC 的条件）。</li><li>在 BFC 中，盒子从包含块的顶部开始，在垂直方向上一个接一个的排列。相邻盒子之间的垂直间隙由它们的 margin 值决定。在同一个 BFC 中，相邻块级盒子的垂直外边距会合并（注：参与 BFC 布局的都是块级元素）。</li><li>在 BFC 中，每一个盒子的左外边缘（margin-left）会触碰到包含块的左边缘。即使是存在浮动元素也是如此，除非该盒子建立了一个新的 BFC。</li></ol><p>结合规范第三点与独立<strong>格式化上下文</strong>的知识，我们可以有以下推论：</p><ol><li>BFC 内外互不影响。</li></ol><ul><li>BFC 包含内部的浮动（解决内部浮动元素导致的高度塌陷）。</li><li>BFC 排斥外部的浮动（触发 BFC 的元素不会和外部的浮动元素重叠）。</li><li>外边距折叠的计算不能跨越 BFC 的边界。</li></ul><ol start="2"><li>各自创建了 BFC 的兄弟元素互不影响（注：在水平方向上多个浮动元素加一个或零个触发 BFC 的元素可以形成多列布局）。</li></ol><p>通过 BFC 可以实现灵活健壮的自适应布局，在一行中达到类似 flexbox 的效果，示例如下：</p><p><strong>两栏自适应布局</strong><img src="'+n+'" alt="" loading="lazy"></p><p><strong>多列自适应布局</strong><img src="'+r+'" alt="" loading="lazy"></p>',43)])])}const g=l(c,[["render",s]]);export{u as __pageData,g as default};
